/* Container input gate.
 *
 * The container path exists so a user can hand ds4 a file, not so it can invent
 * a second way to prepare frames: ffmpeg decodes to raw RGB and everything
 * after that is the frame-list path.  The checks below pin exactly that down.
 *
 * The fixture is generated by ffmpeg itself, so the gate needs no checked-in
 * video and no network.
 */
#include "ds4.h"
#include "ds4_image.h"
#include "ds4_video.h"

#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/wait.h>
#include <unistd.h>

static void require(int ok, const char *message) {
    if (!ok) {
        fprintf(stderr, "FAIL: %s\n", message);
        exit(1);
    }
}

/* ffmpeg -f lavfi -i testsrc ... writes a deterministic clip; -y overwrites. */
static int make_fixture(const char *path) {
    const pid_t pid = fork();
    if (pid < 0) return 0;
    if (pid == 0) {
        execlp("ffmpeg", "ffmpeg", "-nostdin", "-v", "error", "-y",
               "-f", "lavfi", "-i", "testsrc=size=224x224:rate=8:duration=2",
               "-pix_fmt", "yuv420p", path, (char *)NULL);
        _exit(127);
    }
    int status = 0;
    if (waitpid(pid, &status, 0) < 0) return 0;
    return WIFEXITED(status) && WEXITSTATUS(status) == 0;
}

int main(int argc, char **argv) {
    if (argc < 3 || argc > 4) {
        fprintf(stderr,
                "usage: %s MAIN.gguf MMPROJ.gguf [CONTAINER.mp4]\n", argv[0]);
        return 2;
    }
    if (!ds4_video_tools_available()) {
        fprintf(stderr,
                "ds4-video-test: skipped (ffmpeg/ffprobe not in PATH)\n");
        return 0;
    }

    char fixture_path[128] = {0};
    const char *container = argc == 4 ? argv[3] : NULL;
    if (!container) {
        snprintf(fixture_path, sizeof(fixture_path), "/tmp/ds4-video-%d.mp4",
                 (int)getpid());
        require(make_fixture(fixture_path), "fixture generation with ffmpeg");
        container = fixture_path;
    }

    uint32_t width = 0, height = 0;
    double duration = 0.0;
    char error[256] = {0};
    require(ds4_video_probe(container, &width, &height, &duration, error,
                            sizeof(error)),
            error[0] ? error : "probe");
    fprintf(stderr, "ds4-video-test: %s %ux%u %.3fs\n", container, width,
            height, duration);

    /* The sampling policy is deterministic: the same request gives the same
     * frame count and the same pixels, and the count respects the request. */
    ds4_video_frames a = {0};
    require(ds4_video_decode_file(container, 4u, &a, error, sizeof(error)),
            error[0] ? error : "decode 4 frames");
    require(a.count == 4u && a.width == width && a.height == height,
            "requested frame count not honoured");

    ds4_video_frames b = {0};
    require(ds4_video_decode_file(container, 4u, &b, error, sizeof(error)),
            error[0] ? error : "decode again");
    require(b.count == a.count, "frame count is not deterministic");
    const size_t frame_bytes = (size_t)a.width * a.height * 3u;
    for (size_t i = 0; i < a.count; i++) {
        require(memcmp(a.frames[i].fingerprint, b.frames[i].fingerprint, 32) == 0,
                "frame fingerprint is not deterministic");
        require(memcmp(a.frames[i].rgb, b.frames[i].rgb, frame_bytes) == 0,
                "decoded pixels are not deterministic");
    }
    /* Distinct frames must fingerprint differently, or a cache hit could serve
     * the wrong video. */
    require(memcmp(a.frames[0].fingerprint, a.frames[1].fingerprint, 32) != 0,
            "different frames share a fingerprint");
    ds4_video_frames_free(&b);

    /* The engine side must accept the decoded sequence and produce a finite,
     * correctly shaped embedding. */
    ds4_engine_options options = {0};
    options.model_path = argv[1];
    options.vision_path = argv[2];
    options.backend = DS4_BACKEND_CUDA;
    options.context_size = 256;
    ds4_engine *engine = NULL;
    require(ds4_engine_open(&engine, &options) == 0, "engine open");
    require(ds4_engine_has_vision(engine), "vision sidecar not available");

    ds4_vision_embedding video = {0};
    require(ds4_engine_vision_encode_video_file(engine, container, 4u, &video,
                                               error, sizeof(error)),
            error[0] ? error : "video encode");
    const uint32_t dim = ds4_engine_embd_dim(engine);
    const size_t floats = (size_t)video.token_count * dim;
    double sum = 0.0;
    int finite = video.data != NULL && video.token_count != 0u;
    for (size_t i = 0; finite && i < floats; i++) {
        finite = isfinite(video.data[i]);
        sum += video.data[i];
    }
    require(finite, "video embedding is empty or non-finite");
    require(video.grid_time == 2u && video.token_count == 2u * 49u,
            "4 sampled frames must merge into two temporal groups");
    fprintf(stderr, "ds4-video-test: 4 frames -> grid_time %u, %u tokens, "
            "sum %.9f\n", video.grid_time, video.token_count, sum);

    /* The container path must add a decoder, not a second way to prepare
     * pixels: the same sampled frames handed over as PNG files have to produce
     * the very same embedding. */
    {
        char fps_arg[64];
        snprintf(fps_arg, sizeof(fps_arg), "fps=%.6f", 4.0 / duration);
        char pattern[160];
        snprintf(pattern, sizeof(pattern), "/tmp/ds4-video-%d-%%d.png",
                 (int)getpid());
        const pid_t pid = fork();
        require(pid >= 0, "fork for the frame extraction");
        if (pid == 0) {
            execlp("ffmpeg", "ffmpeg", "-nostdin", "-v", "error", "-y",
                   "-i", container, "-vf", fps_arg, "-frames:v", "4",
                   pattern, (char *)NULL);
            _exit(127);
        }
        int status = 0;
        require(waitpid(pid, &status, 0) >= 0 && WIFEXITED(status) &&
                    WEXITSTATUS(status) == 0,
                "frame extraction for the equivalence check");
        char png[4][160];
        const char *png_paths[4];
        for (size_t i = 0; i < 4u; i++) {
            snprintf(png[i], sizeof(png[i]), "/tmp/ds4-video-%d-%zu.png",
                     (int)getpid(), i + 1u);
            png_paths[i] = png[i];
        }
        ds4_vision_embedding as_frames = {0};
        require(ds4_engine_vision_encode_frame_files(
                    engine, png_paths, 4u, &as_frames, error, sizeof(error)),
                error[0] ? error : "frame-list encode");
        require(as_frames.token_count == video.token_count,
                "container and frame list disagree on the token count");
        require(memcmp(as_frames.data, video.data,
                       (size_t)video.token_count * dim * sizeof(float)) == 0,
                "container and frame list produced different embeddings");
        ds4_vision_embedding_free(&as_frames);
        for (size_t i = 0; i < 4u; i++) unlink(png[i]);
        fprintf(stderr,
                "ds4-video-test: container and frame list agree bit for bit\n");
    }

    /* Re-encoding must reuse the same identity, or every server request would
     * miss its checkpoint. */
    ds4_vision_embedding again = {0};
    require(ds4_engine_vision_encode_video_file(engine, container, 4u, &again,
                                               error, sizeof(error)),
            error[0] ? error : "video encode again");
    require(again.token_count == video.token_count &&
            memcmp(again.fingerprint, video.fingerprint,
                   sizeof(video.fingerprint)) == 0,
            "container identity is not stable across decodes");
    ds4_vision_embedding_free(&again);
    ds4_vision_embedding_free(&video);
    ds4_engine_close(engine);
    ds4_video_frames_free(&a);
    if (argc != 4) unlink(fixture_path);
    puts("Qwen3-VL container input PASS");
    return 0;
}
